//! The one async command of slice 5c: adding a pack by its link. The job waits on the network and on the secret store, so the command is an
//! `async fn` that the runtime drives, not a blocking one on a pool thread.
// The `unreachable!` clippy reports is generated by `#[tauri::command]` for an async command that borrows `State`; this file holds that one
// command so that the allowance covers nothing else. (The workspace denies `unreachable!` in app code, ADR-0011.)
#![allow(clippy::unreachable)]

use super::{JobContext, STICKER_PACK_PROGRESS, StickerShell, run_job};
use crate::capture::MAIN_LABEL;
use kinige_domain::stickers::{StickerPackAdded, StickerPackProgress};
use kinige_domain::{ApiError, ErrorCode};
use kinige_store::Store;
use std::sync::Arc;
use tauri::{AppHandle, Emitter, Runtime, State};

/// Adds a pack by its link (`https://t.me/addstickers/<name>`, `t.me/addstickers/<name>` or the name). One job at a time: a second call
/// is `sticker_pack_busy`. The token is read here, once, off the main thread; progress goes to the main window as counts. Returns after the
/// pack is written, or with an error and nothing written.
#[tauri::command]
pub async fn add_sticker_pack<R: Runtime>(
    app: AppHandle<R>,
    store: State<'_, Store>,
    shell: State<'_, StickerShell>,
    link: String,
) -> Result<StickerPackAdded, ApiError> {
    let slot = shell.begin().ok_or(ErrorCode::StickerPackBusy)?;
    let client = shell
        .client()
        .map_err(|_| ErrorCode::StickerPackUnreachable)?;
    let sink = app.clone();
    let context = JobContext {
        store: store.inner().clone(),
        client,
        secrets: shell.secrets.clone(),
        cancel: slot.cancel.clone(),
        progress: Arc::new(move |progress: StickerPackProgress| {
            let _ = sink.emit_to(MAIN_LABEL, STICKER_PACK_PROGRESS, progress);
        }),
    };
    let result = run_job(&context, &link).await;
    drop(slot);
    if let Err(error) = &result {
        // The category only: never the link, the pack name, a title or the token.
        log::warn!("sticker pack: {:?}", error.code);
    }
    result
}
